function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }

const j = $json;
const sql = `INSERT INTO trading.stock_price_history
  (symbol, trading_date, close, source)
  VALUES (${pgStr(j.ticker)}, ${pgStr(j.datum)}, ${pgNum(j.aktueller_kurs)}, 'technische-signale-02')
  ON CONFLICT (symbol, trading_date) DO UPDATE SET
    close = EXCLUDED.close, source = EXCLUDED.source, fetched_at = now();`;
return { json: { ...j, sql } };

const items = $input.all().map(i => i.json).filter(i => i.ticker !== undefined);
const total = items.length;
const errorItems = items.filter(i => i.status === 'fehler' || i.fehler);
const successful = total - errorItems.length;
const failed = errorItems.length;

let status;
if (total === 0) status = 'skipped';
else if (failed === 0) status = 'success';
else if (successful === 0) status = 'failed';
else status = 'partial_failure';

let startedAt = null;
try { startedAt = $('Watchlist laden (Kurse)').all()[0].json._run_started_at; } catch (e) {}
let runId = null;
try { runId = $('Execute Workflow Trigger').all()[0].json.context.run_id; } catch (e) {}

return [{ json: {
  ok: failed === 0,
  workflow: '02 \u2013 Technische Signale t\u00e4glich',
  run_id: runId,
  processed: total,
  successful,
  failed,
  warnings: [],
  errors: errorItems.map(i => ({ ticker: i.ticker, node: 'Kurs abrufen (lokaler FastAPI)', message: i.fehler || 'Unbekannter Fehler' })),
  started_at: startedAt,
  finished_at: new Date().toISOString(),
  status
} }];
